using Mirage;using Mirage.Serialization;using UnityEngine;
namespace GunmageddonAudio
{
    internal struct C127PoseCue{internal uint Source;internal byte Mount;internal float Yaw,Pitch;internal double Time;}
    internal struct C127ShotCue{internal uint Source,Sequence;internal byte Mount,Gun;internal bool Air;internal float Fuse;internal double Time;internal GlobalPosition Position;internal Quaternion Rotation;}
    internal struct C127BurstCue{internal uint Source;internal GlobalPosition Point;internal double Time;}
    internal static partial class F88FlakNetwork
    {
        static void InstallC127(){Writer<C127PoseCue>.Write=(w,m)=>{w.WriteUInt32(m.Source);w.WriteByte(m.Mount);w.WriteSingle(m.Yaw);w.WriteSingle(m.Pitch);w.WriteDouble(m.Time);};Reader<C127PoseCue>.Read=r=>new C127PoseCue{Source=r.ReadUInt32(),Mount=r.ReadByte(),Yaw=r.ReadSingle(),Pitch=r.ReadSingle(),Time=r.ReadDouble()};Writer<C127ShotCue>.Write=(w,m)=>{w.WriteUInt32(m.Source);w.WriteUInt32(m.Sequence);w.WriteByte(m.Mount);w.WriteByte(m.Gun);w.WriteByte(m.Air?(byte)1:(byte)0);w.WriteSingle(m.Fuse);w.WriteDouble(m.Time);w.WriteSingle(m.Position.x);w.WriteSingle(m.Position.y);w.WriteSingle(m.Position.z);w.WriteSingle(m.Rotation.x);w.WriteSingle(m.Rotation.y);w.WriteSingle(m.Rotation.z);w.WriteSingle(m.Rotation.w);};Reader<C127ShotCue>.Read=r=>new C127ShotCue{Source=r.ReadUInt32(),Sequence=r.ReadUInt32(),Mount=r.ReadByte(),Gun=r.ReadByte(),Air=r.ReadByte()!=0,Fuse=r.ReadSingle(),Time=r.ReadDouble(),Position=new GlobalPosition(r.ReadSingle(),r.ReadSingle(),r.ReadSingle()),Rotation=new Quaternion(r.ReadSingle(),r.ReadSingle(),r.ReadSingle(),r.ReadSingle())};Writer<C127BurstCue>.Write=(w,m)=>{w.WriteUInt32(m.Source);w.WriteSingle(m.Point.x);w.WriteSingle(m.Point.y);w.WriteSingle(m.Point.z);w.WriteDouble(m.Time);};Reader<C127BurstCue>.Read=r=>new C127BurstCue{Source=r.ReadUInt32(),Point=new GlobalPosition(r.ReadSingle(),r.ReadSingle(),r.ReadSingle()),Time=r.ReadDouble()};MessagePacker.RegisterMessage<C127PoseCue>();MessagePacker.RegisterMessage<C127ShotCue>();MessagePacker.RegisterMessage<C127BurstCue>();}
        static void C127Handlers(NetworkClient c,bool add){if(!c)return;if(add){c.MessageHandler.RegisterHandler<C127PoseCue>(ReceiveC127Pose,false);c.MessageHandler.RegisterHandler<C127ShotCue>(ReceiveC127Shot,false);c.MessageHandler.RegisterHandler<C127BurstCue>(ReceiveC127Burst,false);}else{c.MessageHandler.UnregisterHandler<C127PoseCue>();c.MessageHandler.UnregisterHandler<C127ShotCue>();c.MessageHandler.UnregisterHandler<C127BurstCue>();}}
        internal static void C127Pose(Unit owner,byte mount,float yaw,float pitch){if(!server||!owner)return;var id=owner.GetComponent<NetworkIdentity>();if(id&&id.NetId!=0)foreach(var p in Peers)p.Send(new C127PoseCue{Source=id.NetId,Mount=mount,Yaw=yaw,Pitch=pitch,Time=server.World.Time.Time},Channel.Unreliable);}
        internal static void C127Shot(Unit owner,byte mount,byte gun,bool air,float fuse,uint sequence,GlobalPosition position,Quaternion rotation){if(!server||!owner)return;var id=owner.GetComponent<NetworkIdentity>();if(id&&id.NetId!=0)foreach(var p in Peers)p.Send(new C127ShotCue{Source=id.NetId,Mount=mount,Gun=gun,Air=air,Fuse=fuse,Sequence=sequence,Time=server.World.Time.Time,Position=position,Rotation=rotation},Channel.Reliable);}
        internal static void C127Burst(uint source,GlobalPosition point){if(server)foreach(var p in Peers)p.Send(new C127BurstCue{Source=source,Point=point,Time=server.World.Time.Time},Channel.Reliable);}
        static C127Controller ResolveC127(uint source,byte mount){NetworkIdentity id;if(!Receiving||!client.World.TryGetIdentity(source,out id))return null;var unit=id.GetComponent<Unit>();return unit?C127Runtime.Find(unit,mount):null;}
        static void ReceiveC127Pose(INetworkPlayer sender,C127PoseCue m){if(!Receiving||!Finite(m.Yaw)||!Finite(m.Pitch)||Mathf.DeltaAngle(0,m.Pitch)< -85||Mathf.DeltaAngle(0,m.Pitch)>10||double.IsNaN(m.Time)||double.IsInfinity(m.Time))return;double age=client.World.Time.Time-m.Time;if(age< -1||age>2)return;var c=ResolveC127(m.Source,m.Mount);if(c)c.RemotePose(m.Yaw,m.Pitch,m.Time);}
        internal static bool ValidC127Shot(C127ShotCue m,double now){if(!Finite(m.Fuse)||m.Fuse<.3||m.Fuse>40||double.IsNaN(m.Time)||double.IsInfinity(m.Time)||double.IsNaN(now)||double.IsInfinity(now)||!Finite(m.Position.x)||!Finite(m.Position.y)||!Finite(m.Position.z)||!Finite(m.Rotation.x)||!Finite(m.Rotation.y)||!Finite(m.Rotation.z)||!Finite(m.Rotation.w))return false;double age=now-m.Time;float norm=m.Rotation.x*m.Rotation.x+m.Rotation.y*m.Rotation.y+m.Rotation.z*m.Rotation.z+m.Rotation.w*m.Rotation.w;return age>=-1&&age<=2&&norm>.99f&&norm<1.01f;}
        static void ReceiveC127Shot(INetworkPlayer sender,C127ShotCue m){if(!Receiving||!ValidC127Shot(m,client.World.Time.Time))return;double age=client.World.Time.Time-m.Time;var c=ResolveC127(m.Source,m.Mount);if(c)c.RemoteShot(m.Gun,m.Air,m.Fuse,m.Sequence,m.Position,m.Rotation,m.Time,(float)System.Math.Max(0,age));}
        static void ReceiveC127Burst(INetworkPlayer sender,C127BurstCue m){if(!Receiving||!Finite(m.Point.x)||!Finite(m.Point.y)||!Finite(m.Point.z)||double.IsNaN(m.Time)||double.IsInfinity(m.Time))return;double age=client.World.Time.Time-m.Time;if(age< -1||age>20)return;var c=ResolveC127(m.Source,0);var effect=C127Rounds.PuffTemplate;if(c)effect=HarmonyLib.AccessTools.Field(typeof(Gun),"selfDestructEffect").GetValue(c.States[0].Gun) as GameObject;F88FlakEffects.Play(effect,m.Point,(float)System.Math.Max(0,age));}
    }
}
